 b=w.chromium.launch(executable_path='/usr/bin/chromium',args=['--no-sandbox']);page=b.new_page(viewport={'width':390,'height':844},is_mobile=True,has_touch=True);errors=[];page.on('pageerror',lambda e:errors.append(str(e)));page.set_content('<script>const store=new Map();Object.defineProperty(window,"localStorage",{value:{setItem:(k,v)=>store.set(k,v),getItem:k=>store.get(k)??null}})</script>'+Path('/mnt/data/Ilha_Viva_Campo_02.html').read_text());page.wait_for_function('window.field && Object.values(sprites).every(i=>i.complete&&i.naturalWidth)');page.evaluate('field.setAuto(false)');ck('1120 cells from v0.42',page.evaluate('field.s.cells.length===1120 && field.s.version===42'));ck('52 original vertebrates',page.evaluate('field.s.animals.length===52'));ck('103 sprites loaded',page.evaluate('Object.keys(sprites).length===103'));ck('movement',page.evaluate('''()=>{let x=field.p.x;field.keys.add('right');field.move(.2);field.keys.clear();return field.p.x>x}'''));ck('target and irrigation',page.evaluate('''()=>{let c=field.target(),v=c.surface; if(!field.perform('water'))return false;field.move(.6);let ok=c.surface===v+20;field.move(.6);return ok&&c.surface===v+20}'''));ck('stationary action and single commit',page.evaluate('''()=>{let x=field.p.x,c=field.target(),v=c.surface;field.perform('water');field.keys.add('left');field.move(.6);field.move(.6);field.keys.clear();return field.p.x===x&&c.surface===v+20&&!field.action}'''));ck('world time advances',page.evaluate('''()=>{let d=field.s.step;field.advance(4);return field.s.step===d+4&&field.steps===4}'''));ck('numeric balance after integrated tick',page.evaluate('Object.values(field.s.last).every(v=>typeof v!=="number"||Math.abs(v)<1e-6)'));ck('rest',page.evaluate('''()=>{field.p.energy=40;field.rest();return field.p.energy>60}'''));ck('harvest and inventory',page.evaluate('''()=>{let c=field.target();c.phase='fruto';c.fruit=.04;c.fruitN=.003;let prev=field.p.bag.fruit;field.perform('harvest');field.move(.6);field.move(.6);return c.fruit===0&&field.p.bag.fruit>prev}'''));ck('eat',page.evaluate('''()=>{field.p.food=30;let prev=field.p.bag.fruit;field.eat();return field.p.food>30&&field.p.bag.fruit<prev}'''));ck('save load',page.evaluate('''()=>{let x=field.p.x;field.save();field.p.x+=10;field.load();return field.p.x===x}'''));ck('river uses swimming and blocks tools',page.evaluate('''()=>{let c=field.s.cells.find(c=>c.channel);c.surface=12;field.p.x=(c.x+.5)*72;field.p.y=(c.y+.5)*50;return isWater(field.cell(field.p.x,field.p.y))&&!field.perform('water')}'''));page.evaluate('field.newWorld()');page.screenshot(path='/mnt/data/Ilha_Viva_Campo_02_preview.png',full_page=True);ck('no JS errors',not errors);ck('mobile no horizontal overflow',page.evaluate('document.documentElement.scrollWidth<=innerWidth'));print(json.dumps({'passed':len(checks),'checks':checks,'errors':errors},ensure_ascii=False,indent=2));b.close()
